import os
import net.http
import net.http.mime
import json
import encoding.base64
import crypto.hmac
import crypto.sha256
import crypto.rand
import time
import x.json2 as json2
import sqlite

const (
    max_tokens = 65000
)

struct User {
    id      string
    email   string
    name    string
    picture string
}

struct Message {
    role      string
    content   string
    timestamp string
}

struct Conversation {
    id         string
    user_id    string
    title      string
    created_at string
    messages   string // JSON encoded string
}

struct ChatRequest {
    message          string
    conversation_id  ?string
}

struct CerebrasClient {
    api_key string
}

struct Choice {
    message struct {
        content string
    }
}

struct CerebrasResponse {
    choices []Choice
}

fn (c &CerebrasClient) chat_completions(messages []map[string]string) ?CerebrasResponse {
    url := ''
    payload := {
        'model':       'gpt-oss-120b'
        'messages':    messages
        'max_tokens':  max_tokens
        'temperature': 1.0
        'top_p':       0.95
    }
    json_payload := json.encode(payload)
    mut req := http.new_request(.post, url, json_payload) ?
    req.header.add(.authorization, 'Bearer ${c.api_key}')
    req.header.add(.content_type, 'application/json')
    resp := req.do() ?
    if resp.status_code != 200 {
        return error('Cerebras API error: ${resp.body}')
    }
    return json.decode(CerebrasResponse, resp.body) ?
}

fn get_cerebras_client() ?&CerebrasClient {
    api_key := os.getenv('CEREBRAS_API_KEY')
    if api_key == '' {
        return error('CEREBRAS_API_KEY environment variable is not set')
    }
    return &CerebrasClient{api_key: api_key}
}

fn generate_conversation_id() string {
    return rand.uuid_v4()
}

fn get_conversation_title(message string) string {
    if message.len > 200 {
        return message[..200]
    }
    return message
}

fn init_db() ? {
    db := sqlite.connect('conversations.db') ?
    db.exec("PRAGMA journal_mode = WAL;")
    db.exec('
        CREATE TABLE IF NOT EXISTS conversations (
            id TEXT PRIMARY KEY,
            user_id TEXT NOT NULL,
            title TEXT NOT NULL,
            created_at TEXT NOT NULL,
            messages TEXT NOT NULL
        );
    ')
    db.exec('CREATE INDEX IF NOT EXISTS idx_user_id ON conversations(user_id);')
    db.close()
}

fn get_user_from_session(session_map map[string]string) ?User {
    if 'user' !in session_map {
        return none
    }
    user_json := session_map['user']
    user := json.decode(User, user_json) ?
    return user
}

fn main() {
    init_db() or { panic(err) }

    mut server := http.Server{
        port: 5000
        handler: fn (mut req http.Request) http.Response {
            mut resp := http.new_response()
            resp.header.set(.server, 'vweb')

            path := req.url
            method := req.method

            match true {
                path == '/' {
                    resp.set_file('index.html', '.') or { return resp }
                }
                path == '/login' {
                    kinde_host := os.getenv_opt('KINDE_HOST') or { '' }
                    client_id := os.getenv_opt('KINDE_CLIENT_ID') or { return resp.set_status(.internal_server_error).text('Missing Kinde config') }
                    redirect_uri := os.getenv_opt('KINDE_REDIRECT_URI') or { return resp.set_status(.internal_server_error).text('Missing Kinde config') }
                    provider := req.url_query()['provider'] or { '' }

                    state := rand.uuid_v4()
                    req.session_set('oauth_state', state)

                    mut auth_url := '${kinde_host}/oauth2/auth?response_type=code&client_id=${client_id}&redirect_uri=${redirect_uri}&scope=openid profile email&state=${state}'
                    if provider != '' {
                        auth_url += '&connection=${provider}'
                    }
                    return resp.redirect(auth_url)
                }
                path == '/register' {
                    kinde_host := os.getenv_opt('KINDE_HOST') or { '' }
                    client_id := os.getenv_opt('KINDE_CLIENT_ID') or { return resp.set_status(.internal_server_error).text('Missing Kinde config') }
                    redirect_uri := os.getenv_opt('KINDE_REDIRECT_URI') or { return resp.set_status(.internal_server_error).text('Missing Kinde config') }

                    state := rand.uuid_v4()
                    req.session_set('oauth_state', state)

                    auth_url := '${kinde_host}/oauth2/auth?response_type=code&client_id=${client_id}&redirect_uri=${redirect_uri}&scope=openid profile email&state=${state}&start_page=registration'
                    return resp.redirect(auth_url)
                }
                path == '/callback' {
                    code := req.url_query()['code'] or { return resp.redirect('/?error=no_code') }
                    state := req.url_query()['state'] or { return resp.redirect('/?error=invalid_state') }

                    expected_state := req.session_get('oauth_state') or { return resp.redirect('/?error=invalid_state') }
                    if state != expected_state {
                        return resp.redirect('/?error=invalid_state')
                    }
                    req.session_delete('oauth_state')

                    kinde_host := os.getenv_opt('KINDE_HOST') or { '' }
                    client_id := os.getenv_opt('KINDE_CLIENT_ID') or { return resp.redirect('/?error=kinde_config_missing') }
                    client_secret := os.getenv_opt('KINDE_CLIENT_SECRET') or { return resp.redirect('/?error=kinde_config_missing') }
                    redirect_uri := os.getenv_opt('KINDE_REDIRECT_URI') or { return resp.redirect('/?error=kinde_config_missing') }

                    token_resp := http.post_form('${kinde_host}/oauth2/token', {
                        'grant_type':     'authorization_code'
                        'code':           code
                        'redirect_uri':   redirect_uri
                        'client_id':      client_id
                        'client_secret':  client_secret
                    }) or { return resp.redirect('/?error=token_exchange_failed') }

                    if token_resp.status_code != 200 {
                        return resp.redirect('/?error=token_exchange_failed')
                    }

                    tokens := json2.raw_decode(token_resp.body) or { return resp.redirect('/?error=token_exchange_failed') }.as_map()
                    access_token := tokens['access_token']?.str() or { return resp.redirect('/?error=token_exchange_failed') }

                    user_resp := http.fetch(http.FetchConfig{
                        url: '${kinde_host}/oauth2/v2/user_profile'
                        header: http.new_header_from_map({
                            .authorization: 'Bearer ${access_token}'
                        })
                    }) or { return resp.redirect('/?error=profile_fetch_failed') }

                    if user_resp.status_code != 200 {
                        return resp.redirect('/?error=profile_fetch_failed')
                    }

                    user_data := json2.raw_decode(user_resp.body) or { return resp.redirect('/?error=profile_fetch_failed') }.as_map()
                    user := User{
                        id: user_data['sub']?.str() or { '' }
                        email: user_data['email']?.str() or { '' }
                        name: user_data['name']?.str() or { user_data['preferred_username']?.str() or { user_data['email']?.str()?.split('@')[0] or { '' } } }
                        picture: user_data['picture']?.str() or { '' }
                    }

                    req.session_set('user', json.encode(user))
                    return resp.redirect('/')
                }
                path == '/logout' {
                    req.session_clear()
                    kinde_host := os.getenv_opt('KINDE_HOST') or { '' }
                    logout_redirect := os.getenv_opt('LOGOUT_REDIRECT_URL') or { '/' }
                    return resp.redirect('${kinde_host}/logout?redirect=${logout_redirect}')
                }
                path == '/api/auth/status' {
                    user := get_user_from_session(req.session_map) or { return resp.json({'authenticated': false}) }
                    return resp.json({
                        'authenticated': true
                        'user':          user
                    })
                }
                path == '/api/chat' && method == .post {
                    user := get_user_from_session(req.session_map) or {
                        return resp.status(.unauthorized).json({'error': 'Bejelentkezés szükséges', 'redirect': '/login'})
                    }

                    body := req.data
                    req_data := json.decode(ChatRequest, body) or { return resp.status(.bad_request).json({'error': 'Invalid JSON'}) }

                    message := req_data.message.trim_space()
                    if message == '' {
                        return resp.status(.bad_request).json({'error': 'Message is required'})
                    }

                    mut conversation_id := req_data.conversation_id or { '' }
                    user_id := user.id

                    db := sqlite.connect('conversations.db') or { return resp.status(.internal_server_error).json({'error': 'DB error'}) }

                    if conversation_id == '' {
                        conversation_id = generate_conversation_id()
                        title := get_conversation_title(message)
                        created_at := time.now().format_ss()
                        db.exec_param_many('INSERT INTO conversations (id, user_id, title, created_at, messages) VALUES (?, ?, ?, ?, ?)',
                            [conversation_id, user_id, title, created_at, '[]']) or { db.close(); return resp.status(.internal_server_error).json({'error': 'DB insert failed'}) }
                    } else {
                        row := db.exec_one('SELECT 1 FROM conversations WHERE id = ? AND user_id = ?', conversation_id, user_id) or { db.close(); return resp.status(.not_found).json({'error': 'Conversation not found'}) }
                        if row.vals.len == 0 {
                            db.close()
                            return resp.status(.not_found).json({'error': 'Conversation not found'})
                        }
                    }

                    messages_json := db.exec_one('SELECT messages FROM conversations WHERE id = ? AND user_id = ?', conversation_id, user_id) or { db.close(); return resp.status(.internal_server_error).json({'error': 'DB error'}) }
                    mut messages := json.decode([]Message, messages_json.vals[0]) or { [] }

                    user_msg := Message{
                        role: 'user'
                        content: message
                        timestamp: time.now().format_ss()
                    }
                    messages << user_msg

                    system_prompt := [
                        {
                            'role': 'system'
                            'content': 'Végig magyarul válaszolj. A válaszaidat szép formázással készítsd, tiszta szöveggel. Ne használj markdown karaktereket (*,#,`,[,],stb.). Ha listák szükségesek, egyszerű számozás vagy felsorolás használj. A válaszod legyen olvasható, logikus és jól szerkesztett.'
                        }
                    ]
                    mut api_messages := system_prompt.clone()
                    for m in messages {
                        api_messages << {
                            'role': m.role
                            'content': m.content
                        }
                    }

                    client := get_cerebras_client() or { db.close(); return resp.status(.internal_server_error).json({'error': 'Cerebras client error'}) }
                    cerebras_resp := client.chat_completions(api_messages) or { db.close(); return resp.status(.internal_server_error).json({'error': 'Cerebras API error'}) }

                    assistant_message := cerebras_resp.choices[0].message.content

                    assistant_msg := Message{
                        role: 'assistant'
                        content: assistant_message
                        timestamp: time.now().format_ss()
                    }
                    messages << assistant_msg

                    db.exec_param_many('UPDATE conversations SET messages = ? WHERE id = ? AND user_id = ?',
                        [json.encode(messages), conversation_id, user_id]) or { db.close(); return resp.status(.internal_server_error).json({'error': 'DB update failed'}) }

                    db.close()

                    return resp.json({
                        'conversation_id': conversation_id
                        'response':        assistant_message
                        'messages':        messages
                    })
                }
                path == '/api/conversations' && method == .get {
                    user := get_user_from_session(req.session_map) or {
                        return resp.status(.unauthorized).json({'error': 'Bejelentkezés szükséges'})
                    }
                    db := sqlite.connect('conversations.db') or { return resp.status(.internal_server_error).json({'error': 'DB error'}) }
                    rows := db.exec('SELECT id, title, created_at, messages FROM conversations WHERE user_id = ? ORDER BY created_at DESC', user.id) or { db.close(); return resp.status(.internal_server_error).json({'error': 'DB error'}) }
                    mut list := []map[string]json2.Any{}
                    for row in rows {
                        messages := json.decode([]Message, row.vals[3]) or { [] }
                        list << {
                            'id':             row.vals[0]
                            'title':          row.vals[1]
                            'created_at':     row.vals[2]
                            'message_count':  messages.len.str()
                        }
                    }
                    db.close()
                    return resp.json(list)
                }
                path.starts_with('/api/conversations/') && method == .get {
                    conv_id := path.split('/')[3]
                    user := get_user_from_session(req.session_map) or {
                        return resp.status(.unauthorized).json({'error': 'Bejelentkezés szükséges'})
                    }
                    db := sqlite.connect('conversations.db') or { return resp.status(.internal_server_error).json({'error': 'DB error'}) }
                    row := db.exec_one('SELECT id, title, created_at, messages FROM conversations WHERE id = ? AND user_id = ?', conv_id, user.id) or { db.close(); return resp.status(.not_found).json({'error': 'Conversation not found'}) }
                    if row.vals.len == 0 {
                        db.close()
                        return resp.status(.not_found).json({'error': 'Conversation not found'})
                    }
                    messages := json.decode([]Message, row.vals[3]) or { [] }
                    db.close()
                    return resp.json({
                        'id':          row.vals[0]
                        'title':       row.vals[1]
                        'created_at':  row.vals[2]
                        'messages':    messages
                    })
                }
                path.starts_with('/api/conversations/') && method == .delete {
                    conv_id := path.split('/')[3]
                    user := get_user_from_session(req.session_map) or {
                        return resp.status(.unauthorized).json({'error': 'Bejelentkezés szükséges'})
                    }
                    db := sqlite.connect('conversations.db') or { return resp.status(.internal_server_error).json({'error': 'DB error'}) }
                    row := db.exec_one('SELECT user_id FROM conversations WHERE id = ?', conv_id) or { db.close(); return resp.status(.not_found).json({'error': 'Conversation not found'}) }
                    if row.vals.len == 0 || row.vals[0] != user.id {
                        db.close()
                        return resp.status(.forbidden).json({'error': 'Access denied'})
                    }
                    db.exec_param('DELETE FROM conversations WHERE id = ? AND user_id = ?', conv_id, user.id) or { db.close(); return resp.status(.internal_server_error).json({'error': 'DB error'}) }
                    db.close()
                    return resp.json({'success': true})
                }
                path == '/api/health' {
                    return resp.json({
                        'status':     'ok'
                        'model':      'TiffyAI'
                        'max_tokens': max_tokens
                    })
                }
                else {
                    resp.set_status(.not_found)
                    resp.text('Not found')
                }
            }
            return resp
        }
    }

    server.listen_and_serve()
}

