                    messages_json := db.exec_one('SELECT messages FROM conversations WHERE id = ? AND user_id = ?', conversation_id, user_id) or { db.close(); return resp.status(.internal_server_error).json({'error': 'DB error'}) }
                    mut messages := json.decode([]Message, messages_json.vals[0]) or { [] }

                    user_msg := Message{
                        role: 'user'
                        content: message
                        timestamp: time.now().format_ss()
                    }
                    messages << user_msg

                    system_prompt := [
                        {
                            'role': 'system'
                            'content': 'Végig magyarul válaszolj. A válaszaidat szép formázással készítsd, tiszta szöveggel. Ne használj markdown karaktereket (*,#,`,[,],stb.). Ha listák szükségesek, egyszerű számozás vagy felsorolás használj. A válaszod legyen olvasható, logikus és jól szerkesztett.'
                        }
                    ]
                    mut api_messages := system_prompt.clone()
                    for m in messages {
                        api_messages << {
                            'role': m.role
                            'content': m.content
                        }
                    }

                    client := get_cerebras_client() or { db.close(); return resp.status(.internal_server_error).json({'error': 'Cerebras client error'}) }
                    cerebras_resp := client.chat_completions(api_messages) or { db.close(); return resp.status(.internal_server_error).json({'error': 'Cerebras API error'}) }

                    assistant_message := cerebras_resp.choices[0].message.content

                    assistant_msg := Message{
                        role: 'assistant'
                        content: assistant_message
                        timestamp: time.now().format_ss()
                    }
                    messages << assistant_msg

                    db.exec_param_many('UPDATE conversations SET messages = ? WHERE id = ? AND user_id = ?',
                        [json.encode(messages), conversation_id, user_id]) or { db.close(); return resp.status(.internal_server_error).json({'error': 'DB update failed'}) }

                    db.close()

                    return resp.json({
                        'conversation_id': conversation_id
                        'response':        assistant_message
                        'messages':        messages
                    })
                }
                path == '/api/conversations' && method == .get {
                    user := get_user_from_session(req.session_map) or {
                        return resp.status(.unauthorized).json({'error': 'Bejelentkezés szükséges'})
                    }
                    db := sqlite.connect('conversations.db') or { return resp.status(.internal_server_error).json({'error': 'DB error'}) }
                    rows := db.exec('SELECT id, title, created_at, messages FROM conversations WHERE user_id = ? ORDER BY created_at DESC', user.id) or { db.close(); return resp.status(.internal_server_error).json({'error': 'DB error'}) }
                    mut list := []map[string]json2.Any{}
                    for row in rows {
                        messages := json.decode([]Message, row.vals[3]) or { [] }
                        list << {
                            'id':             row.vals[0]
                            'title':          row.vals[1]
                            'created_at':     row.vals[2]
                            'message_count':  messages.len.str()
                        }
                    }
                    db.close()
                    return resp.json(list)
                }
                path.starts_with('/api/conversations/') && method == .get {
                    conv_id := path.split('/')[3]
                    user := get_user_from_session(req.session_map) or {
                        return resp.status(.unauthorized).json({'error': 'Bejelentkezés szükséges'})
                    }
                    db := sqlite.connect('conversations.db') or { return resp.status(.internal_server_error).json({'error': 'DB error'}) }
                    row := db.exec_one('SELECT id, title, created_at, messages FROM conversations WHERE id = ? AND user_id = ?', conv_id, user.id) or { db.close(); return resp.status(.not_found).json({'error': 'Conversation not found'}) }
                    if row.vals.len == 0 {
                        db.close()
                        return resp.status(.not_found).json({'error': 'Conversation not found'})
                    }
                    messages := json.decode([]Message, row.vals[3]) or { [] }
                    db.close()
                    return resp.json({
                        'id':          row.vals[0]
                        'title':       row.vals[1]
                        'created_at':  row.vals[2]
                        'messages':    messages
                    })
                }
                path.starts_with('/api/conversations/') && method == .delete {
                    conv_id := path.split('/')[3]
                    user := get_user_from_session(req.session_map) or {
                        return resp.status(.unauthorized).json({'error': 'Bejelentkezés szükséges'})
                    }
                    db := sqlite.connect('conversations.db') or { return resp.status(.internal_server_error).json({'error': 'DB error'}) }
                    row := db.exec_one('SELECT user_id FROM conversations WHERE id = ?', conv_id) or { db.close(); return resp.status(.not_found).json({'error': 'Conversation not found'}) }
                    if row.vals.len == 0 || row.vals[0] != user.id {
                        db.close()
                        return resp.status(.forbidden).json({'error': 'Access denied'})
                    }
                    db.exec_param('DELETE FROM conversations WHERE id = ? AND user_id = ?', conv_id, user.id) or { db.close(); return resp.status(.internal_server_error).json({'error': 'DB error'}) }
                    db.close()
                    return resp.json({'success': true})
                }
                path == '/api/health' {
                    return resp.json({
                        'status':     'ok'
                        'model':      'TiffyAI'
                        'max_tokens': max_tokens
                    })
                }
                else {
                    resp.set_status(.not_found)
                    resp.text('Not found')
                }
            }
            return resp
        }
    }

    server.listen_and_serve()
}
